export function renderNarrativeDetail(data) {
  const n = data.spread || {};
  const f = data.finding || {};
  const related = (data.relatedClusters || []).map((x) => `<li><a href="/dashboard/cluster/${esc(x.id)}">${esc(x.label || x.id)}</a></li>`).join('') || '<li class="muted">No related clusters.</li>';
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Narrative Detail</title><style>body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#0b1020;color:#e8ecf1}.card{background:#121a2b;border:1px solid #25314a;border-radius:14px;padding:14px;margin-bottom:14px}a{color:#8ec5ff}.muted{color:#9aa4b2}ul{padding-left:18px}.timeline{display:flex;gap:6px;flex-wrap:wrap}.bin{background:#0f1727;border:1px solid #23304a;border-radius:8px;padding:6px;min-width:88px}</style></head><body><p><a href="/dashboard">← Back to dashboard</a></p><div class="card"><h1>${esc(f.label || n.label || n.id)}</h1><p>${esc(f.summary || '')}</p><p class="muted">first_seen=${esc(n.first_seen)} last_seen=${esc(n.last_seen)} span_minutes=${esc(n.span_minutes)}</p></div><div class="card"><h2>Findings</h2><ul>${(f.findings || []).map((x) => `<li>${esc(x)}</li>`).join('')}</ul></div><div class="card"><h2>Spread</h2><p>subreddits: ${esc((n.subreddits || []).join(', '))}</p><p>authors: ${esc((n.authors || []).join(', '))}</p><p>compressed window: ${esc(n.time_compression_flag)}</p></div><div class="card"><h2>Timeline</h2><div class="timeline">${(n.timeline || []).map((b) => `<span class="bin"><strong>${esc(b.count)}</strong><br><small>${esc(b.bucket_start)}</small></span>`).join('')}</div></div><div class="card"><h2>Related Clusters</h2><ul>${related}</ul></div></body></html>`;
}

export function renderGraphPage(graph) {
  const nodes = graph.nodes || [];
  const edges = graph.edges || [];

  const narratives = nodes.filter((n) => n.type === 'narrative');
  const clusters = nodes.filter((n) => n.type === 'cluster');
  const posts = nodes.filter((n) => n.type === 'post');

  const width = 1200;
  const columnX = { cluster: 180, narrative: 600, post: 1020 };
  const rowGap = 90;
  const topPad = 80;
  const height = Math.max(700, topPad + Math.max(clusters.length, narratives.length, posts.length) * rowGap + 100);

  const positioned = new Map();

  function place(list, type) {
    list.forEach((node, i) => {
      positioned.set(node.id, {
        ...node,
        x: columnX[type],
        y: topPad + i * rowGap
      });
    });
  }

  place(clusters, 'cluster');
  place(narratives, 'narrative');
  place(posts, 'post');

  function color(type) {
    if (type === 'cluster') return '#ffb86b';
    if (type === 'narrative') return '#8ec5ff';
    if (type === 'post') return '#7ee787';
    return '#c9d1d9';
  }

  function href(node) {
    if (node.type === 'cluster') return `/dashboard/cluster/${encodeURIComponent(node.id)}`;
    if (node.type === 'narrative') return `/dashboard/narrative/${encodeURIComponent(node.id)}`;
    return null;
  }

  const edgeSvg = edges.map((e) => {
    const a = positioned.get(e.source);
    const b = positioned.get(e.target);
    if (!a || !b) return '';
    return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="#395178" stroke-width="1.5" opacity="0.8" />`;
  }).join('');

  const nodeSvg = [...positioned.values()].map((n) => {
    const fill = color(n.type);
    const label = esc(n.label || n.id);
    const small = n.type === 'post' ? label.slice(0, 30) : label.slice(0, 40);
    const link = href(n);
    const body = `<g><circle cx="${n.x}" cy="${n.y}" r="16" fill="${fill}" stroke="#0b1020" stroke-width="2" /><text x="${n.x + 24}" y="${n.y + 5}" fill="#e8ecf1" font-size="13">${small}</text></g>`;
    return link ? `<a href="${link}">${body}</a>` : body;
  }).join('');

  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Truth Lens Graph</title><style>body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#0b1020;color:#e8ecf1}.card{background:#121a2b;border:1px solid #25314a;border-radius:14px;padding:14px;margin-bottom:14px}a{color:#8ec5ff}.muted{color:#9aa4b2}.legend{display:flex;gap:16px;flex-wrap:wrap}.legend span{display:inline-flex;align-items:center;gap:6px}.dot{width:12px;height:12px;border-radius:50%;display:inline-block}</style></head><body><p><a href="/dashboard">← Back to dashboard</a></p><div class="card"><h1>Truth Lens Graph</h1><p class="muted">Clusters connect to narratives, which connect to posts. This is a simple deterministic view over the current local dataset.</p><div class="legend"><span><i class="dot" style="background:#ffb86b"></i>Clusters</span><span><i class="dot" style="background:#8ec5ff"></i>Narratives</span><span><i class="dot" style="background:#7ee787"></i>Posts</span></div></div><div class="card"><svg width="100%" viewBox="0 0 ${width} ${height}" preserveAspectRatio="xMinYMin meet"><text x="120" y="36" fill="#9aa4b2" font-size="16">Clusters</text><text x="540" y="36" fill="#9aa4b2" font-size="16">Narratives</text><text x="980" y="36" fill="#9aa4b2" font-size="16">Posts</text>${edgeSvg}${nodeSvg}</svg></div></body></html>`;
}

